using Microsoft.EntityFrameworkCore;\nusing System;\nusing System.Threading.Tasks;\n\nnamespace TransactionExample\n{\n    public class Order\n    {\n        public int Id { get; set; }\n        public int ProductId { get; set; }\n        public int Quantity { get; set; }\n    }\n\n    public class Inventory\n    {\n        public int ProductId { get; set; }\n        public int Quantity { get; set; }\n    }\n\n    public class ApplicationDbContext : DbContext\n    {\n        public DbSet<Order> Orders { get; set; }\n        public DbSet<Inventory> Inventories { get; set; }\n\n        protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)\n        {\n            optionsBuilder.UseSqlServer("Server=(localdb)\mssqllocaldb;Database=TransactionTest;Trusted_Connection=true;TrustServerCertificate=true");\n        }\n    }\n\n    public class OrderService\n    {\n        private readonly ApplicationDbContext _context;\n\n        public OrderService(ApplicationDbContext context)\n        {\n            _context = context;\n        }\n\n        public async Task<bool> ProcessOrder(Order order)\n        {\n            using var transaction = await _context.Database.BeginTransactionAsync();\n            try\n            {\n                // 1. Create order\n                _context.Orders.Add(order);\n                await _context.SaveChangesAsync();\n\n                // 2. Deduct inventory\n                var inventory = await _context.Inventories.FindAsync(order.ProductId);\n                if (inventory == null || inventory.Quantity <= order.Quantity)\n                {\n                    await transaction.RollbackAsync();\n                    return false;\n                }\n\n                inventory.Quantity -= order.Quantity;\n                await _context.SaveChangesAsync();\n\n                // 3. Commit transaction\n                await transaction.CommitAsync();\n                return true;\n            }\n            catch (Exception)\n            {\n                await transaction.RollbackAsync();\n                throw;\n            }\n        }\n    }\n\n    public class Program\n    {\n        public static async Task Main()\n        {\n            var context = new ApplicationDbContext();\n            var service = new OrderService(context);\n\n            var order = new Order { ProductId = 1, Quantity = 2 };\n\n            var success = await service.ProcessOrder(order);\n            Console.WriteLine(success ? "Order processed successfully." : "Failed to process order.");\n\n            await context.Database.EnsureDeletedAsync();\n        }\n    }\n}\n